import {mountProductSearch} from './product-search.js';
import {selectableComponents} from './component-policy.js';
import {choiceDescription,choiceAddon,validateAddon} from './addon-data.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function mountAddonChoices(root,{initial=[],getCosts,sourceId,onChange=()=>{},renderCheck=()=>''}){
 let choices=structuredClone(initial);
 const read=(required=true)=>{const rows=choices.map(c=>{const node=[...root.querySelectorAll('[data-choice]')].find(n=>n.dataset.choice===c.id),raw=node.querySelector('[data-choice-price]').value;
  if(raw!==''&&!/^\d+(\.\d{1,2})?$/.test(raw))throw Error('每项加购价最多两位小数');
  if(!node.querySelector('[data-choice-text-only]').checked&&!c.goodsId)throw Error('请选择加购商品，或勾选仅文字说明');
  return {...c,originalQty:Number(node.querySelector('[data-choice-original-qty]').value),qty:Number(node.querySelector('[data-choice-qty]').value),priceCents:raw===''?null:Math.round(Number(raw)*100),label:node.querySelector('[data-choice-label]').value.trim(),enabled:node.querySelector('[data-choice-enabled]').checked};
 });if(required)validateAddon({text:choiceDescription(rows),choices:rows},{required:true,costs:getCosts()});return rows;};
 function refresh(){try{const rows=read(false);root.querySelector('[data-choice-preview]').textContent=choiceDescription(rows)||'暂不展示加购';for(const c of rows){const node=[...root.querySelectorAll('[data-choice]')].find(n=>n.dataset.choice===c.id);node.querySelector('[data-choice-check]').innerHTML=renderCheck(choiceAddon(c,sourceId));}}catch(e){root.querySelector('[data-choice-preview]').textContent=e.message;}onChange();}
 function draw(){root.innerHTML=`<p class="hint">可添加多个升级商品，也可勾选“仅文字说明”直接填写文案，无需绑定商品。绑定商品时，每项单独填写加购价并检查差价。内存从 1 根升级到 2 根：原配件替换数量填 1，新配件数量填 2。勾选的文案合并在同一条加购描述中。</p><div data-choice-list>${choices.map((c,i)=>`<section class="addon-choice" data-choice="${esc(c.id)}"><div class="actions"><strong>加购商品 ${i+1}</strong><label><input type="checkbox" data-choice-enabled ${c.enabled?'checked':''}> 展示</label><button type="button" data-choice-remove>移除</button></div><label><input type="checkbox" data-choice-text-only ${!c.goodsId?'checked':''}> 仅文字说明（不绑定商品、不核算差价）</label><div data-choice-product ${!c.goodsId?'hidden':''}></div><div class="inline-grid" data-choice-pricing ${!c.goodsId?'hidden':''}><label class="field">原配件替换数量<input type="number" min="1" max="100000" step="1" data-choice-original-qty value="${c.originalQty??1}"></label><label class="field">新配件数量<input type="number" min="1" step="1" data-choice-qty value="${c.qty??1}"></label><label class="field">此商品加购价<input type="number" min="0" step=".01" data-choice-price value="${c.priceCents==null?'':(c.priceCents/100).toFixed(2)}"></label></div><label class="field">展示文案（绑定商品时无需填写金额）<input data-choice-label value="${esc(c.label)}" placeholder="例如：升级250K Plus"></label><div data-choice-check></div></section>`).join('')}</div><button type="button" data-choice-add>＋ 添加加购商品</button><p class="hint">合并展示预览</p><p data-choice-preview class="addon-choice-preview"></p>`;
  for(const c of choices){const node=[...root.querySelectorAll('[data-choice]')].find(n=>n.dataset.choice===c.id);mountProductSearch(node.querySelector('[data-choice-product]'),{getRows:()=>selectableComponents(getCosts()),getCosts,selected:c.goodsId,label:'加购商品',onChange:row=>{c.goodsId=row?.goodsId||'';const label=node.querySelector('[data-choice-label]');if(!label.value.trim()&&row)label.value='升级'+row.name;refresh();}});node.querySelector('[data-choice-text-only]').onchange=e=>{if(e.target.checked)c.goodsId='';node.querySelector('[data-choice-product]').hidden=e.target.checked;node.querySelector('[data-choice-pricing]').hidden=e.target.checked;refresh();};node.querySelector('[data-choice-remove]').onclick=()=>{choices=read(false).filter(v=>v.id!==c.id);draw();refresh();};for(const input of node.querySelectorAll('[data-choice-price],[data-choice-original-qty],[data-choice-qty],[data-choice-label],[data-choice-enabled]'))input.addEventListener('input',refresh);}
  root.querySelector('[data-choice-add]').onclick=()=>{try{choices=read(false);if(choices.length>=30)throw Error('最多添加 30 个加购商品');choices.push({id:crypto.randomUUID(),goodsId:'',qty:1,originalQty:1,priceCents:null,label:'',enabled:true});draw();refresh();}catch(e){root.querySelector('[data-choice-preview]').textContent=e.message;}};
 }
 draw();refresh();return {read,refresh};
}
